-- Исправление пояснений в 45 вопросах (общие пояснения и пояснения к отдельным вариантам) по независимым проверкам.
-- Источник: scripts/questions/033_explanation_fixes.js; таблица «было → станет»: docs/EXPLANATION-FIXES-2026-10-16.md
-- Повторный запуск безопасен: вопрос ищется по тексту, пояснение должно быть прежним или уже новым, иначе пакет отменяется.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('Какую страницу выбирает алгоритм вытеснения из буферного кеша?', 'explanation', 'Это алгоритм LRU — Least Recently Used: «горячие» данные остаются в кеше.', 'PostgreSQL использует алгоритм clock sweep — приближение LRU: у каждого буфера есть счётчик обращений, при обходе он уменьшается, и вытесняется незакреплённый буфер с нулевым счётчиком. Так «горячие» данные остаются в кеше.'),
        ('Какие библиотеки PostgreSQL использует для сжатия данных?', 'explanation', 'Все эти библиотеки используются, но их можно отключить при сборке.', 'zlib используется по умолчанию и отключается ключом --without-zlib; lz4 и zstd подключаются при сборке явно (--with-lz4, --with-zstd). readline к сжатию не относится: он отвечает за редактирование команд в psql.'),
        ('Какие библиотеки PostgreSQL использует для сжатия данных?', 'A', 'Используется для сжатия; при сборке её можно отключить.', 'Используется для сжатия, если сервер собран с ключом --with-zstd.'),
        ('Какие библиотеки PostgreSQL использует для сжатия данных?', 'C', 'Используется для сжатия; при сборке её можно отключить.', 'Используется для сжатия по умолчанию; отключается при сборке ключом --without-zlib.'),
        ('Какие библиотеки PostgreSQL использует для сжатия данных?', 'D', 'Используется для сжатия; при сборке её можно отключить.', 'Используется для сжатия, если сервер собран с ключом --with-lz4.'),
        ('Что задаёт параметр restore_command при восстановлении из архива?', 'explanation', 'Сервер вызывает её, когда нужного сегмента нет в каталоге pg_wal.', 'Сервер вызывает её, чтобы получить сегмент из архива. Сегмент из архива предпочтительнее файла в pg_wal; в pg_wal сервер ищет только то, чего нет в архиве.'),
        ('Для каких объектов существует слой инициализации (init)?', 'explanation', 'Имена его файлов оканчиваются на _init. После сбоя слой init записывается на место основного, и объект становится пустым.', 'Имена его файлов оканчиваются на _init. После сбоя слой init записывается на место основного: таблица становится пустой, а последовательность возвращается к начальному состоянию.'),
        ('Какой файл параметров сервера считывается последним?', 'explanation', 'Последним считывается postgresql.auto.conf, переопределяя все остальные настройки.', 'Среди файлов конфигурации последним считывается postgresql.auto.conf и перекрывает значения postgresql.conf. Параметры командной строки сервера и установки для базы, роли и сеанса действуют поверх файлов.'),
        ('Что означает значение pending_restart = true в pg_settings?', 'explanation', 'Полный список таких параметров даёт запрос к pg_settings с условием context = postmaster.', 'Параметры с ожидающим перезапуска изменением выбирает условие WHERE pending_restart. Условие context = postmaster даёт все параметры, которые меняются только перезапуском, а не только ожидающие.'),
        ('Почему высокий buffer hit ratio не означает, что остальные блоки читались с диска?', 'explanation', 'Реальные чтения с диска смотрят средствами ОС или по pg_stat_io.', 'Счётчики PostgreSQL, включая blks_read и pg_stat_io, считают обращения к ОС и не отличают чтение с накопителя от чтения из кеша ОС. Реальные обращения к устройствам смотрят средствами ОС, например iostat.'),
        ('Что верно для файла postgresql.auto.conf?', 'explanation', 'Файл управляется только через ALTER SYSTEM; после изменений конфигурацию нужно перечитать, как и для postgresql.conf.', 'ALTER SYSTEM записывает значения в postgresql.auto.conf; после изменений конфигурацию нужно перечитать, как и для postgresql.conf. Файл могут менять и внешние инструменты (например, pg_basebackup -R), но вручную при работающем сервере его править не рекомендуется.'),
        ('К чему приводит отключение автоочистки, если не выполнять очистку и анализ вручную?', 'explanation', 'Автоочистка не работает, если выключен параметр autovacuum или track_counts.', 'Если выключен autovacuum или track_counts, обычная автоочистка и автоматический анализ не работают. Защитная очистка против переполнения счётчика транзакций всё равно может запускаться, но не заменяет обычное обслуживание.'),
        ('Допишите команду, чтобы включить файловую архивацию журналов:
```
ALTER SYSTEM SET archive_mode = ___;
```', 'explanation', 'Также нужна archive_command, а изменение archive_mode требует перезапуска сервера.', 'Также нужна archive_command (или archive_library, начиная с PostgreSQL 15), а изменение archive_mode требует перезапуска сервера.'),
        ('Возвращает ли обычный VACUUM освободившееся место операционной системе?', 'explanation', 'Чтобы уменьшить физический размер файлов, нужна полная очистка.', 'Обычный VACUUM использует освободившееся место внутри таблицы и может отсечь только пустые страницы в конце файла. Чтобы файл стал компактным, нужна полная очистка VACUUM FULL.'),
        ('В какой схеме находятся таблицы и представления системного каталога?', 'explanation', 'Если pg_catalog не указана в пути поиска, она неявно проверяется первой.', 'Если pg_catalog не указана в пути поиска, она неявно просматривается перед явным путём; но при поиске таблиц и типов раньше неё проверяется временная схема pg_temp.'),
        ('Что верно для пути поиска search_path?', 'explanation', 'Новый объект попадает в первую явно указанную схему, а pg_catalog неявно проверяется первой.', 'Новый объект создаётся в первой существующей схеме явного пути, к которой есть доступ и в которой есть право CREATE. Неявная pg_catalog просматривается перед явным путём, а при поиске таблиц и типов раньше неё проверяется временная схема.'),
        ('С какого места начинается восстановление после сбоя?', 'explanation', 'Поэтому хранить нужно только файлы журнала, записанные после последней контрольной точки.', 'Для восстановления после сбоя нужны файлы журнала, начиная с позиции последней завершённой контрольной точки. Более ранние файлы могут понадобиться слотам репликации, архивированию и восстановлению из более старой резервной копии.'),
        ('В каком случае транзакция будет ждать освобождения блокировки строки?', 'explanation', 'Писатели не блокируют читателей, читатели не блокируют никого.', 'Для строк писатели не блокируют читателей, а читатели — писателей. Но обычный SELECT берёт на таблицу блокировку ACCESS SHARE, которая конфликтует с ACCESS EXCLUSIVE, например у DROP TABLE.'),
        ('Что верно для блокировок в PostgreSQL?', 'explanation', 'Транзакция ждёт, только если меняет строку, уже изменённую другой незафиксированной транзакцией.', 'Транзакция ждёт, если ей нужна блокировка, несовместимая с уже удерживаемой: например, она меняет строку, изменённую другой незафиксированной транзакцией, запрашивает SELECT FOR UPDATE по такой строке или несовместимую табличную блокировку. Обычный SELECT блокировку строки не ждёт, но может ждать ACCESS EXCLUSIVE.'),
        ('Допишите команду, чтобы создать таблицу в табличном пространстве ts:
```
CREATE TABLE t (id int) ___ ts;
```', 'explanation', 'Без TABLESPACE таблица создаётся в табличном пространстве по умолчанию для базы.', 'Без TABLESPACE используется параметр default_tablespace, а если он пуст — табличное пространство по умолчанию для базы.'),
        ('Что верно для TOAST?', 'explanation', 'Toast-таблицы лежат в схеме pg_toast, а любая версия строки должна помещаться на одну страницу.', 'Toast-таблицы постоянных таблиц лежат в схеме pg_toast (у временных — в pg_toast_temp_N), а любая версия строки должна помещаться на одну страницу: длинные значения сжимаются и выносятся в toast-таблицу.'),
        ('Что нужно учитывать приложению, работающему через менеджер пула соединений?', 'C', 'Наоборот: с точки зрения сервера число клиентов остаётся постоянным.', 'Число серверных процессов определяется числом серверных соединений пула и его лимитами: оно не обязано ни совпадать с числом клиентов, ни быть постоянным.'),
        ('Для чего нужны схемы?', 'explanation', 'Каждый объект базы данных принадлежит какой-либо схеме.', 'Схемы группируют таблицы, функции, типы и другие объекты, имена которых находятся внутри схемы; не все виды объектов базы данных относятся к схемам.'),
        ('Что изменилось для схемы public начиная с PostgreSQL 15?', 'explanation', 'Если ничего не менять и есть доступ к схеме public, объекты создаются в ней.', 'Начиная с PostgreSQL 15 роль PUBLIC в новых базах по умолчанию не имеет права CREATE на схему public. Одного права USAGE недостаточно для создания объектов: нужно получить и CREATE.'),
        ('Допишите команду psql, чтобы получить список схем вместе с системными:
```
\dn___
```', 'explanation', 'Без модификатора S команды \d показывают только пользовательские объекты.', 'Без модификатора S команды \d показывают только пользовательские объекты; явный шаблон имени тоже может показать системные.'),
        ('Что такое горизонт очистки?', 'explanation', 'Горизонт один на каждую базу данных.', 'Горизонт определяет, какие удалённые версии строк ещё нельзя вычищать. Для обычных таблиц он один на каждую базу данных; для общих каталогов, локальных каталогов и временных таблиц действуют особые правила.'),
        ('На каком уровне определяется горизонт очистки?', 'C', 'Так сказано в курсе: горизонт один на каждую базу данных.', 'Для обычных таблиц горизонт определяется по транзакциям базы данных. Для общих и локальных каталогов и временных таблиц правила особые.'),
        ('Что даёт включение hot_standby_feedback?', 'D', 'Пока работает соединение, очистка на мастере не удаляет версии, нужные запросам реплики; old_snapshot_threshold это ограничение не отменяет.', 'Пока работает соединение, реплика сообщает мастеру горизонт своих запросов, и очистка на мастере не удаляет версии, нужные этим запросам.'),
        ('Какие свойства транзакций в первую очередь обеспечивает многоверсионность?', 'explanation', 'Многоверсионность обеспечивает атомарность, согласованность и изоляцию; долговечность — журнал предзаписи.', 'Многоверсионность обеспечивает изоляцию (снимки данных) и атомарность (версии строк прерванной транзакции остаются невидимыми); долговечность обеспечивает журнал предзаписи. Согласованность обеспечивают ограничения целостности.'),
        ('Какое значение параметра stats_fetch_consistency используется по умолчанию?', 'explanation', 'cache — компромисс: кешируется статистика по одному объекту.', 'При cache статистика каждого запрошенного объекта кешируется при первом обращении до конца транзакции; snapshot кеширует сразу всю статистику текущей базы, none не кеширует ничего.'),
        ('Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', 'explanation', 'Уменьшить индекс помогает перестроение командой REINDEX.', 'Частично заполненные страницы B-дерева не объединяются; полностью пустые страницы исключаются из дерева и используются повторно, но файл индекса сам не уменьшается. Уменьшить индекс помогает перестроение командой REINDEX.'),
        ('Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', 'A', 'Даже если из них удалены все индексные записи.', 'Частично заполненные страницы после расщепления не объединяются; полностью пустые используются повторно, но файл индекса не сжимается.'),
        ('Для чего нужны блокировки на уровне таблиц?', 'explanation', 'На практике удаление и перестроение таблиц выполняются редко и обычно не мешают работе.', 'Табличные блокировки согласуют доступ: SELECT защищает таблицу от удаления, а операции перестроения могут требовать ACCESS EXCLUSIVE и блокировать другие обращения.'),
        ('Начиная с какой версии PostgreSQL публикация может передавать только часть данных таблицы: набор столбцов и строки по условию?', 'explanation', 'Публикация может включать несколько таблиц одной базы данных.', 'Списки публикуемых столбцов и фильтры строк (WHERE) в публикациях появились в PostgreSQL 15; в версии 16 добавился параметр подписки origin.'),
        ('Какая утилита из состава PostgreSQL запускает и останавливает сервер и показывает его статус?', 'explanation', 'pg_ctlcluster — обёртка над pg_ctl, она есть только в пакетах Ubuntu и Debian.', 'pg_ctl входит в стандартную поставку и умеет start, stop, restart, reload и status; pg_ctlcluster — обёртка над ним только в пакетах Debian и Ubuntu.'),
        ('Где в пакете Ubuntu находится каталог данных кластера main версии 16?', 'explanation', 'Пакет размещает файлы по правилам, принятым в Ubuntu.', 'В пакете Ubuntu данные кластера лежат в /var/lib/postgresql/<версия>/<имя>, конфигурация — в /etc/postgresql/<версия>/<имя>, программы — в /usr/lib/postgresql/<версия>.'),
        ('На каких уровнях можно установить параметры конфигурации?', 'explanation', 'В курсе эти уровни рассматриваются в порядке от общего к частному.', 'Параметры задаются для всего экземпляра в файлах конфигурации, для базы или роли командами ALTER DATABASE и ALTER ROLE … SET и для сеанса командой SET; более частный уровень перекрывает более общий. Допустимые уровни зависят от контекста параметра.'),
        ('Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', 'explanation', 'Это одно из заданий практики курса.', 'Чтение таблицы удерживает блокировку ACCESS SHARE до конца транзакции. DROP TABLE требует несовместимую с ней блокировку ACCESS EXCLUSIVE и поэтому ждёт.'),
        ('Что такое схема в PostgreSQL?', 'explanation', 'Схема и пользователь в PostgreSQL — разные сущности.', 'Схема — пространство имён внутри базы данных: объекты с одинаковыми именами могут лежать в разных схемах, а полное имя записывают как схема.объект.'),
        ('Допишите команду, чтобы приоритет имела схема с именем пользователя, а затем app:
```
SET search_path = ___;
```', 'explanation', 'Это одно из заданий практики курса.', 'Схемы в search_path просматриваются слева направо. Запись "$user" в двойных кавычках подставляет имя текущей роли: такая схема используется, если она существует и доступна, затем app.'),
        ('Допишите команду psql, чтобы получить список всех представлений схемы information_schema:
```
\dv ___
```', 'explanation', 'Это одно из заданий практики курса.', 'В шаблонах psql часть до точки задаёт схему, а после неё — имя объекта; * означает любые символы, поэтому information_schema.* выбирает все представления этой схемы.'),
        ('Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', 'C', 'Так сказано в курсе.', 'Начиная с PostgreSQL 14 у большинства таблиц каталога объявлены первичные ключи и ограничения уникальности (раньше существовали только уникальные индексы).'),
        ('Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', 'D', 'Об этом в курсе речи нет: появились первичные ключи и ограничения уникальности.', 'Настоящих внешних ключей в системном каталоге нет; связи между его таблицами можно посмотреть функцией pg_get_catalog_foreign_keys().'),
        ('Что нужно, чтобы удалить табличное пространство командой DROP TABLESPACE?', 'explanation', 'В практике курса созданное табличное пространство в конце удаляют.', 'DROP TABLESPACE удаляет только пустое табличное пространство: объекты всех баз кластера сначала удаляют или переносят командой ALTER … SET TABLESPACE.'),
        ('Что задают параметры seq_page_cost и random_page_cost?', 'explanation', 'Их подробно рассматривают в курсе QPT «Оптимизация запросов».', 'Это условные единицы стоимости, которыми планировщик сравнивает планы; на скорость дисков они не влияют.'),
        ('Как объекты хранятся внутри каталога табличного пространства?', 'explanation', 'Подробнее о файлах объектов — в теме о низкоуровневом хранении.', 'Каждая таблица и каждый индекс хранятся в собственных файлах — слоях, разбитых на сегменты по 1 ГБ; все объекты базы в один общий файл не складываются.'),
        ('Какого размера достигает файл слоя, прежде чем создаётся следующий сегмент?', 'explanation', '16 МБ — это размер сегмента WAL по умолчанию, а не файла данных.', 'Файл слоя по умолчанию разбивается на сегменты по 1 ГБ; размер задаётся при сборке. 16 МБ — размер сегмента WAL, а 8 КБ — размер страницы.'),
        ('Почему pg_database_size возвращает больше, чем сумма размеров пользовательских таблиц базы?', 'explanation', 'Это одно из заданий практики курса.', 'pg_database_size считает все файлы базы: кроме пользовательских таблиц это системный каталог, индексы, toast-таблицы и служебные слои fsm и vm.'),
        ('Какой столбец pg_stat_user_tables показывает примерное число мёртвых версий строк?', 'explanation', 'В практике курса эти цифры сопоставляют с выполненными действиями.', 'n_dead_tup — оценка числа мёртвых версий строк; по ней автоочистка решает, пора ли обрабатывать таблицу. Это не накопительный счётчик удалений: его показывает n_tup_del.'),
        ('При synchronous_commit = on и заданной синхронной реплике реплику остановили. Что будет с фиксацией изменяющих транзакций на основном сервере?', 'explanation', 'Синхронный режим повышает надёжность, но замедляет работу.', 'Мастер ждёт подтверждения от синхронной реплики: пока оно не получено, COMMIT не завершается, хотя запись о фиксации уже есть в локальном журнале. Автоматического перехода в асинхронный режим нет.')
    ) AS fixes(question_text, field, old_text, new_text)
    LOOP
        IF fix.field = 'explanation' THEN
            SELECT count(*) INTO matches FROM questions
            WHERE question_text = fix.question_text AND explanation IN (fix.old_text, fix.new_text);
        ELSE
            SELECT count(*) INTO matches FROM questions
            WHERE question_text = fix.question_text AND option_notes ->> fix.field IN (fix.old_text, fix.new_text);
        END IF;
        IF matches <> 1 THEN
            RAISE EXCEPTION 'Не найден единственный вопрос с ожидаемым пояснением';
        END IF;
        IF fix.field = 'explanation' THEN
            UPDATE questions SET explanation = fix.new_text
            WHERE question_text = fix.question_text AND explanation = fix.old_text;
        ELSE
            UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[fix.field], to_jsonb(fix.new_text))
            WHERE question_text = fix.question_text AND option_notes ->> fix.field = fix.old_text;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
